+// Till sales: each dish sold uses one portion of its recipe per qty,
+// consuming ingredients under ledger ref `sale:<ticket>`.
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Set of ticket ids that have already been imported. */
+export function importedTickets(store) {
+  return new Set((store.data.sales ?? []).map((s) => s.ticket));
+}
+
+/** Records one sold dish line and consumes its recipe ingredients from stock. */
+export function recordSale(store, { ticket, soldAt, dishId, qty }) {
+  const dish = getDish(store, dishId);
+  const recipe = getRecipe(store, dish.recipeId);
+  const needs = scaled(recipe, qty);
+  for (const n of needs) {
+    if (n.qty > 0) consume(store, n.itemId, n.qty, { at: soldAt, ref: `sale:${ticket}` });
+  }
+  store.data.sales ??= [];
+  const sale = { id: store.nextId("sale"), ticket, soldAt, dishId, qty };
+  store.data.sales.push(sale);
+  return sale;
+}
+
+/** Sales whose UTC day falls between `from` and `to` (inclusive). */
+export function salesBetween(store, from, to) {
+  return (store.data.sales ?? []).filter((s) => {
+    const day = dayOf(s.soldAt);
+    return day >= from && day <= to;
+  });
+}
