diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..446eaa2
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,72 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Tickets already imported are skipped; the whole file is checked (including
+// stock levels) before anything is changed, so one bad row or shortfall
+// imports nothing and names the row.
+import { isInstant } from "../dates.js";
+import { AppError } from "../errors.js";
+import { getItem, onHand } from "../domain/items.js";
+import { scaled } from "../domain/recipes.js";
+import { importedTickets, recordSale } from "../domain/sales.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** Imports sales CSV; returns { tickets, dishes } imported or throws naming the row. */
+export function importSales(store, text) {
+  const [head = [], ...rawRows] = parseCsv(text);
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const parsed = rawRows.map((raw, i) => {
+    const where = `row ${i + 2}`;
+    const r = Object.fromEntries(keys.map((k, idx) => [k, (raw[idx] ?? "").trim()]));
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const soldAt = r.soldAt.endsWith("Z") ? r.soldAt : new Date(r.soldAt).toISOString();
+    const dishId = Number(r.dishId);
+    if (!r.dishId || !Number.isInteger(dishId) || dishId < 1) {
+      throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    }
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const recipe = store.data.recipes.find((rec) => rec.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: unknown recipe ${dish.recipeId}` });
+    const qty = Number(r.qty);
+    if (!r.qty || !Number.isInteger(qty) || qty < 1) {
+      throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    }
+    return { where, ticket: r.ticket, soldAt, dishId, recipe, qty };
+  });
+
+  const known = importedTickets(store);
+  const todo = parsed.filter((row) => !known.has(row.ticket));
+
+  const remaining = new Map();
+  for (const row of todo) {
+    for (const n of scaled(row.recipe, row.qty)) {
+      if (n.qty <= 0) continue;
+      const item = getItem(store, n.itemId);
+      if (!remaining.has(n.itemId)) remaining.set(n.itemId, round3(onHand(store, n.itemId)));
+      const available = remaining.get(n.itemId);
+      if (available < n.qty) {
+        throw new AppError("not_enough_stock", {
+          item: `${item.name} (${row.where})`,
+          available,
+          unit: item.unit,
+        });
+      }
+      remaining.set(n.itemId, round3(available - n.qty));
+    }
+  }
+
+  const newTickets = new Set();
+  let dishes = 0;
+  for (const row of todo) {
+    recordSale(store, { ticket: row.ticket, soldAt: row.soldAt, dishId: row.dishId, qty: row.qty });
+    newTickets.add(row.ticket);
+    dishes += row.qty;
+  }
+  return { tickets: newTickets.size, dishes };
+}
